UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{ 
    "All": {
        "Claimed": " WITH d1 AS ( SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ), workflowkeys AS ( SELECT workflowkey FROM ui.workflowmasters WHERE ( workflowid IN ( SELECT mappingid FROM d1 ) OR -1 IN ( SELECT mappingid FROM d1 ) ) AND itenantid = :tenantid AND is_filter_display = true ), filtered_hiproinst AS ( SELECT * FROM camunda.act_hi_procinst WHERE start_time_ BETWEEN :StartDate AND :EndDate AND proc_def_key_ IN (SELECT workflowkey FROM workflowkeys) AND tenant_id_ = :tenantidstr LIMIT 30000  ), ranked_oplog AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY time_ DESC) AS rn FROM camunda.act_hi_detail WHERE name_ = ''userActivity'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), ticket_data AS ( SELECT proc_inst_id_, long_ AS Case_ID FROM camunda.act_ru_variable WHERE name_ = ''TicketID'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), alert_data AS ( SELECT proc_inst_id_, text_ AS Alert FROM camunda.act_ru_variable WHERE name_ = ''Alert'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ),  payer_cte AS ( SELECT proc_inst_id_, text_ AS payer FROM camunda.act_hi_varinst WHERE name_ = ''payer'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), payee_cte AS ( SELECT proc_inst_id_, text_ AS payee FROM camunda.act_hi_varinst WHERE name_ = ''payee'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), transaction_amount_cte AS ( SELECT proc_inst_id_, double_ / 100 AS amount FROM camunda.act_hi_varinst WHERE name_ = ''TransactionAmount'' AND var_type_ = ''double'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ),   transaction_data AS ( SELECT Txn.proc_inst_id_, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END AS vpa, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''account''->>''vcexternalaccountid'' END AS account, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''customer''->>''vcexternalcustid'' END AS customer FROM camunda.act_hi_varinst Txn JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ WHERE Txn.name_ = ''Transaction'' AND Txn.proc_inst_id_ IN ( SELECT proc_inst_id_ FROM filtered_hiproinst ) ) SELECT task.name_ AS \\"Stage\\", cuser.vcemailid AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", payer_cte.payer AS \\"Payer\\", payee_cte.payee AS \\"Payee\\", transaction_amount_cte.amount AS \\"Amount\\", ticket_data.Case_ID AS \\"Case ID\\", alert_data.Alert AS \\"Alert\\", NULL AS \\"Closed Date\\", NULL AS \\"Closed By\\",   transaction_data.vpa AS \\"VPA\\", transaction_data.account AS \\"Account\\", transaction_data.customer AS \\"Customer\\" FROM camunda.act_ru_task task INNER JOIN filtered_hiproinst hiproinst ON hiproinst.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN ui.webuser cuser ON cuser.iuserid = CAST(task.assignee_ AS INTEGER) LEFT JOIN camunda.act_re_procdef pdef ON pdef.id_ = task.proc_def_id_ LEFT JOIN ranked_oplog oplog ON oplog.proc_inst_id_ = task.proc_inst_id_ AND oplog.rn = 1 LEFT JOIN ticket_data ON ticket_data.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN payer_cte ON payer_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN payee_cte ON payee_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_amount_cte ON transaction_amount_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN alert_data ON alert_data.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN transaction_data ON transaction_data.proc_inst_id_ = task.proc_inst_id_ WHERE task.assignee_ IS NOT NULL;",
        "Unclaimed": " WITH d1 AS ( SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ), workflowkeys AS ( SELECT workflowkey FROM ui.workflowmasters WHERE ( workflowid IN ( SELECT mappingid FROM d1 ) OR -1 IN ( SELECT mappingid FROM d1 ) ) AND itenantid = :tenantid AND is_filter_display = true ), filtered_hiproinst AS ( SELECT * FROM camunda.act_hi_procinst WHERE start_time_ BETWEEN :StartDate AND :EndDate AND proc_def_key_ IN (SELECT workflowkey FROM workflowkeys) AND tenant_id_ = :tenantidstr LIMIT 30000  ), ranked_oplog AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY time_ DESC) AS rn FROM camunda.act_hi_detail WHERE name_ = ''userActivity'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), ticket_data AS ( SELECT proc_inst_id_, long_ AS Case_ID FROM camunda.act_ru_variable WHERE name_ = ''TicketID'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), alert_data AS ( SELECT proc_inst_id_, text_ AS Alert FROM camunda.act_ru_variable WHERE name_ = ''Alert'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ),  payer_cte AS ( SELECT proc_inst_id_, text_ AS payer FROM camunda.act_hi_varinst WHERE name_ = ''payer'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), payee_cte AS ( SELECT proc_inst_id_, text_ AS payee FROM camunda.act_hi_varinst WHERE name_ = ''payee'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), transaction_amount_cte AS ( SELECT proc_inst_id_, double_ / 100 AS amount FROM camunda.act_hi_varinst WHERE name_ = ''TransactionAmount'' AND var_type_ = ''double'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ),    transaction_data AS ( SELECT Txn.proc_inst_id_, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END AS vpa, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''account''->>''vcexternalaccountid'' END AS account, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''customer''->>''vcexternalcustid'' END AS customer FROM camunda.act_hi_varinst Txn JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ WHERE Txn.name_ = ''Transaction'' AND Txn.proc_inst_id_ IN ( SELECT proc_inst_id_ FROM filtered_hiproinst ) ) SELECT task.name_ AS \\"Stage\\", cuser.vcemailid AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", payer_cte.payer AS \\"Payer\\", payee_cte.payee AS \\"Payee\\", transaction_amount_cte.amount AS \\"Amount\\", ticket_data.Case_ID AS \\"Case ID\\", alert_data.Alert AS \\"Alert\\", NULL AS \\"Closed Date\\", NULL AS \\"Closed By\\",   transaction_data.vpa AS \\"VPA\\", transaction_data.account AS \\"Account\\", transaction_data.customer AS \\"Customer\\" FROM camunda.act_ru_task task INNER JOIN filtered_hiproinst hiproinst ON hiproinst.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN ui.webuser cuser ON cuser.iuserid = CAST(task.assignee_ AS INTEGER) LEFT JOIN camunda.act_re_procdef pdef ON pdef.id_ = task.proc_def_id_ LEFT JOIN ranked_oplog oplog ON oplog.proc_inst_id_ = task.proc_inst_id_ AND oplog.rn = 1 LEFT JOIN ticket_data ON ticket_data.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN payer_cte ON payer_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN payee_cte ON payee_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_amount_cte ON transaction_amount_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN alert_data ON alert_data.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN transaction_data ON transaction_data.proc_inst_id_ = task.proc_inst_id_ WHERE task.assignee_ IS NULL;",
        "All": "  WITH filtered_hiproinst AS ( SELECT hiproinst.* FROM camunda.act_hi_procinst hiproinst WHERE hiproinst.start_time_ >= :StartDate   AND hiproinst.start_time_ <= :EndDate AND hiproinst.state_ != ''EXTERNALLY_TERMINATED'' AND hiproinst.proc_def_key_ IN ( WITH d1 AS ( SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ) SELECT workflowkey FROM ui.workflowmasters WHERE ( workflowid IN (SELECT mappingid FROM d1) OR -1 IN (SELECT mappingid FROM d1) ) AND itenantid = :tenantid AND is_filter_display = true ) AND hiproinst.tenant_id_ = :tenantidstr LIMIT 30000 ), ranked_closedby AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC) AS rn FROM camunda.act_hi_taskinst WHERE proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), ranked_oplog AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY time_ DESC) AS rn FROM camunda.act_hi_detail WHERE name_ = ''userActivity'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), payer_cte AS ( SELECT proc_inst_id_, text_ AS payer FROM camunda.act_hi_varinst WHERE name_ = ''payer'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), payee_cte AS ( SELECT proc_inst_id_, text_ AS payee FROM camunda.act_hi_varinst WHERE name_ = ''payee'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), transaction_amount_cte AS ( SELECT proc_inst_id_, double_ / 100 AS amount FROM camunda.act_hi_varinst WHERE name_ = ''TransactionAmount'' AND var_type_ = ''double'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), ticket_id_cte AS ( SELECT proc_inst_id_, long_ AS case_id FROM camunda.act_hi_varinst WHERE name_ = ''TicketID'' AND var_type_ IN (''long'', ''integer'') AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), alert_cte AS ( SELECT proc_inst_id_, text_ AS alert FROM camunda.act_hi_varinst WHERE name_ = ''Alert'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), transaction_data AS ( SELECT Txn.proc_inst_id_, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END AS vpa, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''account''->>''vcexternalaccountid'' END AS account, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''customer''->>''vcexternalcustid'' END AS customer FROM camunda.act_hi_varinst Txn JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ WHERE Txn.name_ = ''Transaction'' AND Txn.proc_inst_id_ IN ( SELECT proc_inst_id_ FROM filtered_hiproinst ) )  SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN wuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", hiproinst.end_time_ AS \\"Closed Date\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", wu.vcemailid AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", payer_cte.payer AS \\"Payer\\", payee_cte.payee AS \\"Payee\\", transaction_amount_cte.amount AS \\"Amount\\", ticket_id_cte.case_id AS \\"Case ID\\", alert_cte.alert AS \\"Alert\\",   transaction_data.vpa AS \\"VPA\\", transaction_data.account AS \\"Account\\", transaction_data.customer AS \\"Customer\\" FROM filtered_hiproinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ LEFT JOIN ranked_closedby closedby ON closedby.proc_inst_id_ = hiproinst.proc_inst_id_ AND closedby.rn = 1 LEFT JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ui.webuser wu ON wu.iuserid = CAST(task.assignee_ AS INTEGER) LEFT JOIN ranked_oplog oplog ON oplog.proc_inst_id_ = task.proc_inst_id_ AND oplog.rn = 1 LEFT JOIN ui.webuser wuser ON wuser.iuserid = CAST(closedby.assignee_ AS INTEGER) LEFT JOIN payer_cte ON payer_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN payee_cte ON payee_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_amount_cte ON transaction_amount_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ticket_id_cte ON ticket_id_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN alert_cte ON alert_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_data ON transaction_data.proc_inst_id_ = task.proc_inst_id_ ;",
        "Closed": "  WITH filtered_hiproinst AS ( SELECT hiproinst.* FROM camunda.act_hi_procinst hiproinst WHERE hiproinst.start_time_ >= :StartDate   AND hiproinst.start_time_ <= :EndDate AND hiproinst.state_ = ''COMPLETED'' AND hiproinst.proc_def_key_ IN ( WITH d1 AS ( SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND mappingtype = ''Workflow'' ) SELECT workflowkey FROM ui.workflowmasters WHERE ( workflowid IN (SELECT mappingid FROM d1) OR -1 IN (SELECT mappingid FROM d1) ) AND itenantid = :tenantid AND is_filter_display = true ) AND hiproinst.tenant_id_ = :tenantidstr LIMIT 30000 ), ranked_closedby AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC) AS rn FROM camunda.act_hi_taskinst WHERE proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), ranked_oplog AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY time_ DESC) AS rn FROM camunda.act_hi_detail WHERE name_ = ''userActivity'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), payer_cte AS ( SELECT proc_inst_id_, text_ AS payer FROM camunda.act_hi_varinst WHERE name_ = ''payer'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), payee_cte AS ( SELECT proc_inst_id_, text_ AS payee FROM camunda.act_hi_varinst WHERE name_ = ''payee'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), transaction_amount_cte AS ( SELECT proc_inst_id_, double_ / 100 AS amount FROM camunda.act_hi_varinst WHERE name_ = ''TransactionAmount'' AND var_type_ = ''double'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), ticket_id_cte AS ( SELECT proc_inst_id_, long_ AS case_id FROM camunda.act_hi_varinst WHERE name_ = ''TicketID'' AND var_type_ IN (''long'', ''integer'') AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), alert_cte AS ( SELECT proc_inst_id_, text_ AS alert FROM camunda.act_hi_varinst WHERE name_ = ''Alert'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), transaction_data AS ( SELECT Txn.proc_inst_id_, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END AS vpa, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''account''->>''vcexternalaccountid'' END AS account, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''customer''->>''vcexternalcustid'' END AS customer FROM camunda.act_hi_varinst Txn JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ WHERE Txn.name_ = ''Transaction'' AND Txn.proc_inst_id_ IN ( SELECT proc_inst_id_ FROM filtered_hiproinst ) ) SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN wuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", hiproinst.end_time_ AS \\"Closed Date\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", wu.vcemailid AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", payer_cte.payer AS \\"Payer\\", payee_cte.payee AS \\"Payee\\", transaction_amount_cte.amount AS \\"Amount\\", ticket_id_cte.case_id AS \\"Case ID\\", alert_cte.alert AS \\"Alert\\",   transaction_data.vpa AS \\"VPA\\", transaction_data.account AS \\"Account\\", transaction_data.customer AS \\"Customer\\" FROM filtered_hiproinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ LEFT JOIN ranked_closedby closedby ON closedby.proc_inst_id_ = hiproinst.proc_inst_id_ AND closedby.rn = 1 LEFT JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ui.webuser wu ON wu.iuserid = CAST(task.assignee_ AS INTEGER) LEFT JOIN ranked_oplog oplog ON oplog.proc_inst_id_ = task.proc_inst_id_ AND oplog.rn = 1 LEFT JOIN ui.webuser wuser ON wuser.iuserid = CAST(closedby.assignee_ AS INTEGER) LEFT JOIN payer_cte ON payer_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN payee_cte ON payee_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_amount_cte ON transaction_amount_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ticket_id_cte ON ticket_id_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN alert_cte ON alert_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_data ON transaction_data.proc_inst_id_ = task.proc_inst_id_ ;"
    },
    "Other": {
        "Claimed": "  WITH  filtered_hiproinst AS ( SELECT * FROM camunda.act_hi_procinst WHERE start_time_ BETWEEN :StartDate AND :EndDate  AND tenant_id_ = :tenantidstr LIMIT 30000  ), ranked_oplog AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY time_ DESC) AS rn FROM camunda.act_hi_detail WHERE name_ = ''userActivity'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), ticket_data AS ( SELECT proc_inst_id_, long_ AS Case_ID FROM camunda.act_ru_variable WHERE name_ = ''TicketID'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), alert_data AS ( SELECT proc_inst_id_, text_ AS Alert FROM camunda.act_ru_variable WHERE name_ = ''Alert'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ),  payer_cte AS ( SELECT proc_inst_id_, text_ AS payer FROM camunda.act_hi_varinst WHERE name_ = ''payer'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), payee_cte AS ( SELECT proc_inst_id_, text_ AS payee FROM camunda.act_hi_varinst WHERE name_ = ''payee'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), transaction_amount_cte AS ( SELECT proc_inst_id_, double_ / 100 AS amount FROM camunda.act_hi_varinst WHERE name_ = ''TransactionAmount'' AND var_type_ = ''double'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ),    transaction_data AS ( SELECT Txn.proc_inst_id_, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END AS vpa, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''account''->>''vcexternalaccountid'' END AS account, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''customer''->>''vcexternalcustid'' END AS customer FROM camunda.act_hi_varinst Txn JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ WHERE Txn.name_ = ''Transaction'' AND Txn.proc_inst_id_ IN ( SELECT proc_inst_id_ FROM filtered_hiproinst ) )  SELECT task.name_ AS \\"Stage\\", cuser.vcemailid AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", payer_cte.payer AS \\"Payer\\", payee_cte.payee AS \\"Payee\\", transaction_amount_cte.amount AS \\"Amount\\", ticket_data.Case_ID AS \\"Case ID\\", alert_data.Alert AS \\"Alert\\", NULL AS \\"Closed Date\\", NULL AS \\"Closed By\\",   transaction_data.vpa AS \\"VPA\\", transaction_data.account AS \\"Account\\", transaction_data.customer AS \\"Customer\\" FROM camunda.act_ru_task task INNER JOIN filtered_hiproinst hiproinst ON hiproinst.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN ui.webuser cuser ON cuser.iuserid = CAST(task.assignee_ AS INTEGER) LEFT JOIN camunda.act_re_procdef pdef ON pdef.id_ = task.proc_def_id_ LEFT JOIN ranked_oplog oplog ON oplog.proc_inst_id_ = task.proc_inst_id_ AND oplog.rn = 1 LEFT JOIN ticket_data ON ticket_data.proc_inst_id_ = task.proc_inst_id_ LEFT JOIN alert_data ON alert_data.proc_inst_id_ = task.proc_inst_id_  LEFT JOIN payer_cte ON payer_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN payee_cte ON payee_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_amount_cte ON transaction_amount_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_data ON transaction_data.proc_inst_id_ = task.proc_inst_id_ WHERE task.assignee_ IS NOT NULL and task.proc_def_id_ in (SELECT id_ FROM camunda.act_re_procdef where key_ = :CaseType and tenant_id_= :tenantidstr) ;", 
