ytes_, ''UTF8'') AS jsonb)->0->''observations''->''vpa''->>''vcexternaladdressid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''vpa''->>''vcexternaladdressid'' END AS vpa, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''account''->>''vcexternalaccountid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''account''->>''vcexternalaccountid'' END AS account, CASE WHEN jsonb_typeof(CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)) = ''array'' THEN CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->0->''observations''->''customer''->>''vcexternalcustid'' ELSE CAST(CONVERT_FROM(Txnorg.bytes_, ''UTF8'') AS jsonb)->''observations''->''customer''->>''vcexternalcustid'' END AS customer FROM camunda.act_hi_varinst Txn JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ WHERE Txn.name_ = ''Transaction'' AND Txn.proc_inst_id_ IN ( SELECT proc_inst_id_ FROM filtered_hiproinst ) ) SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN wuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \\"Closed By\\", hiproinst.end_time_ AS \\"Closed Date\\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \\"Stage\\", wu.vcemailid AS \\"Claimed By\\", hiproinst.start_time_ AS \\"Created Date\\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \\"Status\\", pdef.name_ AS \\"Case Type\\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \\"Claimed On\\", payer_cte.payer AS \\"Payer\\", payee_cte.payee AS \\"Payee\\", transaction_amount_cte.amount AS \\"Amount\\", ticket_id_cte.case_id AS \\"Case ID\\", alert_cte.alert AS \\"Alert\\",   transaction_data.vpa AS \\"VPA\\", transaction_data.account AS \\"Account\\", transaction_data.customer AS \\"Customer\\" FROM filtered_hiproinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ LEFT JOIN ranked_closedby closedby ON closedby.proc_inst_id_ = hiproinst.proc_inst_id_ AND closedby.rn = 1 LEFT JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ui.webuser wu ON wu.iuserid = CAST(task.assignee_ AS INTEGER) LEFT JOIN ranked_oplog oplog ON oplog.proc_inst_id_ = task.proc_inst_id_ AND oplog.rn = 1 LEFT JOIN ui.webuser wuser ON wuser.iuserid = CAST(closedby.assignee_ AS INTEGER) LEFT JOIN payer_cte ON payer_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN payee_cte ON payee_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_amount_cte ON transaction_amount_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ticket_id_cte ON ticket_id_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN alert_cte ON alert_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_data ON transaction_data.proc_inst_id_ = task.proc_inst_id_ ;"
